const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, ImageRun, Header, Footer,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType, PageNumber, LevelFormat,
} = require("docx");

const FONT = "Times New Roman";
const BODY = 22;   // 11 pt
const SMALL = 18;  // 9 pt

// ---------- inline markup: **bold**, *italic* ----------
function runs(text, size = BODY, extra = {}) {
  const out = [];
  const re = /(\*\*[^*]+\*\*|\*[^*]+\*)/g;
  let last = 0, m;
  while ((m = re.exec(text)) !== null) {
    if (m.index > last) out.push(new TextRun({ text: text.slice(last, m.index), font: FONT, size, ...extra }));
    const tok = m[0];
    if (tok.startsWith("**")) out.push(new TextRun({ text: tok.slice(2, -2), bold: true, font: FONT, size, ...extra }));
    else out.push(new TextRun({ text: tok.slice(1, -1), italics: true, font: FONT, size, ...extra }));
    last = m.index + tok.length;
  }
  if (last < text.length) out.push(new TextRun({ text: text.slice(last), font: FONT, size, ...extra }));
  return out;
}
const P = (text, opts = {}) => new Paragraph({
  children: runs(text), alignment: AlignmentType.JUSTIFIED,
  spacing: { after: 140, line: 276 }, ...opts,
});
const H1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1, keepNext: true, spacing: { before: 360, after: 160 },
  children: [new TextRun({ text, bold: true, font: FONT, size: 28 })],
});
const H2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2, keepNext: true, spacing: { before: 240, after: 120 },
  children: [new TextRun({ text, bold: true, font: FONT, size: 24 })],
});
const caption = (text, keepNext = false) => new Paragraph({
  children: runs(text, 20), spacing: { before: 120, after: 120 }, keepNext,
  alignment: AlignmentType.LEFT,
});
const REF = (text) => new Paragraph({
  children: runs(text, 20), spacing: { after: 80 }, indent: { left: 480, hanging: 480 },
});

// ---------- tables ----------
const border = { style: BorderStyle.SINGLE, size: 4, color: "808080" };
const borders = { top: border, bottom: border, left: border, right: border };
function table(widths, header, rows) {
  const total = widths.reduce((a, b) => a + b, 0);
  const mk = (txt, w, isHead, kn = true) => new TableCell({
    borders, width: { size: w, type: WidthType.DXA },
    shading: isHead ? { fill: "E3E8EE", type: ShadingType.CLEAR, color: "auto" } : undefined,
    margins: { top: 60, bottom: 60, left: 90, right: 90 },
    children: [new Paragraph({ keepNext: kn, children: runs(txt, SMALL, isHead ? { bold: true } : {}), spacing: { after: 0 } })],
  });
  return new Table({
    width: { size: total, type: WidthType.DXA }, columnWidths: widths,
    rows: [
      new TableRow({ tableHeader: true, cantSplit: true, children: header.map((h, i) => mk(h, widths[i], true)) }),
      ...rows.map((r, ri) => new TableRow({ cantSplit: true, children: r.map((c, i) => mk(c, widths[i], false, ri < rows.length - 1)) })),
    ],
  });
}
const gap = () => new Paragraph({ children: [], spacing: { after: 120 } });

// ---------- content ----------
const body = [];

// Title block
body.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 120 },
  children: [new TextRun({ text: "An Exploratory Feature-Space Comparison of One-Time and Incremental Adversarial Updates for Network Intrusion Detection", bold: true, font: FONT, size: 34 })] }));
body.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 60 },
  children: [new TextRun({ text: "Ajay Kumar", font: FONT, size: 24 })] }));
body.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 240 },
  children: [new TextRun({ text: "[Affiliation to be supplied]  |  [Email address to be supplied]  |  [Corresponding author to be confirmed]", italics: true, font: FONT, size: 20, color: "555555" })] }));

// ===== Abstract =====
body.push(new Paragraph({ spacing: { before: 120, after: 80 }, keepNext: true, children: [new TextRun({ text: "Abstract", bold: true, font: FONT, size: 24 })] }));
body.push(P("Network intrusion detectors based on machine learning can be evaded by small changes to flow features, and a deployed detector can be updated from the evasions it observes. This offline, exploratory study asks whether repeated updating offers more resistance than one round of adversarial training. It uses one small multilayer perceptron on UNSW-NB15 and attacks that perturb 11 normalized features. It does not generate or validate executable traffic. The attacker is non-adaptive across rounds, and feedback labels are simulated from dataset ground truth. The primary measure is attack-induced ASR, the share of flows detected before perturbation that the attack moves to the benign side, at thresholds that target at most 5% validation FPR. Test FPR is measured separately. In the original five-seed comparison, one-time static adversarial training had lower observed round-5 attack-induced ASR than the frozen model and than incremental updating with clean rehearsal in every seed, but it also received a larger training budget. A 20-seed extension therefore matched the number and source-flow set of attack attempts across one-time and incremental schedules. In the FGSM-like and BIM-like settings, a matched incremental schedule that trains on all attempts had lower observed ASR than a one-time arm with one two-epoch update in 19 of 20 seeds. A one-time arm with one ten-epoch update was lower than it in all 20, and a one-time arm matching its optimizer steps and exposure did not differ from it. The decision-only setting showed no separation. A one-factor sensitivity analysis in the FGSM-like setting gave the same order in seven update configurations. The original static arm stayed lower than its attempt-matched counterpart, so its lower observed ASR goes with its training procedure, not with one-time scheduling. Clean recall and false-positive rate changed little. Most perturbed flows broke relations that hold in the data, so the results measure sensitivity to unconstrained feature perturbations, not evasion with sendable traffic. The study does not show that any update policy is generally superior."));
body.push(new Paragraph({ spacing: { after: 160 }, children: [new TextRun({ text: "Keywords: ", bold: true, italics: true, font: FONT, size: 20 }), new TextRun({ text: "network intrusion detection, adversarial training, incremental learning, evasion attacks, continual learning, UNSW-NB15", italics: true, font: FONT, size: 20 })] }));

// ===== Section 1 =====
body.push(H1("1. Introduction"));
[
"Network intrusion detection systems (NIDS) inspect traffic and label connections or flows as benign or malicious. Deep learning models are attractive for this task, but small, deliberate changes to flow features can move a malicious flow across the decision boundary and cause it to be classified as benign [1]. Surveys of this literature organize attacks by what the attacker knows and by whether perturbations are applied to feature vectors or to the traffic itself [2], and NIDS-specific reviews examine how structured network data differs from the image settings in which most adversarial methods were developed [3].",
"Whether a perturbed feature vector corresponds to traffic that an attacker could actually send is a separate question. Studies of realistic attacks stress that perturbations must respect the constraints of real traffic [4], [5]. Our experiments perturb normalized flow features directly, so the attack success rate (ASR) that we report, which we call attack-induced ASR because it counts only flows detected before perturbation (Section 4.7), describes feature-space vulnerability and should not be read as a rate of end-to-end evasion.",
"Defenses proposed for NIDS include an adversarial training framework [6], simple robustness-enhancing frameworks [7], and approaches aimed at generalized or hybrid robustness [8], [9]. Most such work compares a defended and an undefended model at a single point in time. Deployed detectors, however, can be updated. A defender could confirm evasions that slipped through and use those samples to retrain the model, and this feedback step is the setting studied here. Research on adaptive and continual NIDS addresses data drift, performance degradation, and catastrophic forgetting through meta-learning, memory replay, and comparisons of continual-learning methods [10]–[12]. A recent preprint on dynamic NIDS reports that continuous retraining can reduce attack effectiveness even without adversarial training [13]. Together, these lines of work make repeated updating plausible. The studies we reviewed do not directly compare it with a one-time adversarial training step under a common dataset, a common per-round attacker budget, and a common account of clean-traffic cost, so it remains unclear whether repeated updating is preferable and what it costs in false alarms.",
"Measurement adds a second difficulty. If updating changes how a model scores flows, attack-induced ASR and false-positive rate (FPR) measured at one fixed threshold can describe different operating points for different models, which makes comparisons across update policies hard to interpret. We therefore add a validation-calibrated analysis in which each model receives its own threshold, selected on its own validation data to give at most a 5% false-positive rate there. This procedure does not fix the test false-positive rate at 5%. Test FPR values are measured separately and reported as observed (five-seed means of about 14% to 16% across arms, and 13.22% to 17.02% across the 90 round-5 seed, arm, and attack runs), and the test set is never used to choose a threshold. The primary measure is the attack-induced ASR, the share of flows that a model detects before perturbation and that the attack then moves to the benign side. The post-attack benign rate over all evaluation flows is secondary, and results at the original fixed threshold are kept as a secondary comparison.",
"This paper compares five update policies on the predefined UNSW-NB15 training and test split [14]. They are a frozen clean model, one-time static adversarial training, incremental updates with clean rehearsal, incremental updates without rehearsal, and a balanced-replay variant with a lower learning rate. A sixth, clean-continued control receives the same extra training epochs as the static policy but no adversarial examples. It gives a descriptive comparison of extra clean training under the tested configuration. Because the arms differ in their training data and budgets, the study does not isolate causal effects. In each of five rounds, every policy faces a fresh attack of equal budget that is generated against its own current model. We use an FGSM-like single-step attack, a BIM-like five-step attack, and a decision-only attack that observes hard labels, with five random seeds. In the decision-only evaluation, the static arm is trained using FGSM-like examples, so this is a cross-attack comparison rather than a threat-model-matched static baseline. UNSW-NB15 is a widely cited benchmark [14], but it has documented class overlap and imbalance [15], so we treat the results as a controlled benchmark comparison and not as evidence of deployment performance.",
"The five-seed comparison has a design limit. The static arm trains on 500 adversarial examples, while the incremental arms train on about 21 to 111 successful evasions, so the comparison cannot separate the schedule from the amount of adversarial data. We therefore add a 20-seed extension (Section 4.9) that matches the number and source-flow set of attack attempts. One-time and incremental schedules each train on attempts made on the same 500 adaptation flows, under the same rule within each update. The matched incremental schedule trains on every attempt, not only on successful evasions, so it is a different policy from the original incremental arms. The matched arms also differ in total training exposure unless one is built to match it, and one such arm is included. The extension also adds a static arm trained on decision-only examples, a sensitivity analysis of update settings in the FGSM-like setting, and a measurement of how far the perturbations move flows in raw units and whether they keep relations that hold in the data (Sections 5.8 to 5.10).",
].forEach(t => body.push(P(t)));
body.push(P("The motivating scenario is an interaction in which an attacker adapts to a deployed detector and the defender responds by updating from successful evasions. The experiment in this paper does not model that interaction, because its attacker is non-adaptive (Section 3.1). Section 2 reviews the relevant studies and states the research gap at its end. Section 3 gives the study's aim, objectives, and research questions, and Section 4 describes the method."));

// ===== Section 2 =====
body.push(H1("2. Related Work"));
body.push(P("This section reviews the work that bears most directly on the study. It covers how evasion attacks against network intrusion detection systems (NIDS) are categorized, how realistic feature-space attacks are, how published defenses differ, how detectors are updated over time, and how such comparisons are evaluated. It closes by stating where the present study sits."));
body.push(H2("2.1 Evasion attacks against NIDS"));
body.push(P("Small perturbations that change the output of deep neural networks were widely reported for image classifiers [16]. Adversarial machine learning for NIDS has been surveyed broadly [17]. Vitorino et al. systematize attacks and defenses for intelligent NIDS with a focus on realism, and they define two properties an adversarial example needs in this setting, validity (it follows the structure of network traffic) and coherence (it preserves the functionality of its attack class) [4]. A second way to categorize attacks is by attacker knowledge. In the white-box case the attacker can compute gradients of the detector. The fast gradient sign method (FGSM) takes one step along the sign of the loss gradient [18]. The basic iterative method (BIM) repeats several smaller steps [19], and projected gradient descent (PGD) adds a projection step and, in its usual form, a random start [20]. Gradient-based attacks have been adapted to deep learning NIDS [1], and adversarial examples against NIDS have been studied in their own right [21]. When the attacker sees only the detector's output, decision-based methods apply. Brendel et al. showed that an attack that uses only the final decision of a black-box model can still be reliable [22]."));
body.push(P("The present study uses an FGSM-like attack and a five-step BIM-like attack (no random start) as white-box settings, and a randomized search with a per-sample query limit as a hard-label setting. Table 1 places these settings against the categories used in the literature."));
body.push(caption("**Table 1.** Attack settings in the literature and in this study.", true));
body.push(table([1900, 1500, 3000, 2960],
  ["Attacker knowledge", "Perturbation space", "Representative literature", "In this study"],
  [
    ["White-box (model gradients)", "Feature space", "FGSM [18], BIM [19], PGD [20], applied to NIDS in [1], [21]", "FGSM-like and five-step BIM-like attacks on 11 normalized features"],
    ["Decision-only (hard labels, query limited)", "Feature space", "Decision-based attacks [22]", "Randomized search, at most 50 queries per sample"],
    ["Any", "Problem space (modified traffic)", "[5], [23], [24]", "Not covered"],
  ]));
body.push(gap());
body.push(P("Table 1 shows that every attack in this study sits in the feature-space rows. That choice keeps the attack budget identical across update policies, but it also limits what the results can say, as the next subsection explains."));
body.push(H2("2.2 Feature space versus problem space"));
body.push(P("Most gradient-based attacks perturb feature vectors directly. A real attacker can only change traffic, and a perturbed feature vector may not correspond to any valid flow. Apruzzese et al. modeled realistic attacks against NIDS with this constraint in mind [23], and Merzouk et al. examined how practical evasion attacks on NIDS are [24]. Adv-Bot constructs botnet attacks that are designed to remain realistic [5]. The realism requirement is also the organizing theme of the review in [4]."));
body.push(P("For this paper the consequence is direct. The attacks here change 11 normalized features and do not check that the result could occur in executable traffic. Reported attack-induced ASR values therefore measure how sensitive each detector is to bounded feature perturbations. They should not be read as the evasion rate a real adversary would achieve."));
body.push(H2("2.3 Defenses for NIDS"));
body.push(P("The defenses proposed for NIDS differ in design, so they are better described one by one than as a single group. AIDTF is presented as an adversarial training framework for intrusion detection [6]. Yuan et al. describe a hybrid architecture in which a detector first decides whether an input is adversarial, and a classical machine learning model then makes the final decision for flagged inputs while the deep learning model decides the rest [7]. NIDS-Vis introduces a black-box method that explores the decision boundary around given inputs, and it proposes two training techniques, feature space partitioning and a distributional loss, to improve robustness without substantially reducing performance [8]. Saha et al. combine adversarial training with calibration monitoring and evaluate against FGSM and PGD [9]."));
body.push(P("These works address how to build a more robust detector, using training, input screening, or boundary-aware design. The present study asks a different question. Given a detector that has already been deployed and has been evaded, how should it be updated after successful evasions, and does repeated updating offer anything beyond a single round of adversarial training? Several of the works above also report clean-data behavior alongside robustness, for example [7] and [9], and this study follows that practice because a robustness gain obtained by flagging more benign traffic is not a useful gain. The cost of adversarial training for clean accuracy has been documented for image classifiers [25], which is one reason clean-side measures are reported here."));
body.push(H2("2.4 Updating detectors over time"));
body.push(P("Neural networks that are updated on new data can lose earlier knowledge, a problem known as catastrophic forgetting [26]. Experience replay, which mixes stored earlier examples into later updates, is a standard remedy [27]. In intrusion detection, replay-based continual learning approaches have been proposed [28], and adaptive memory replay has been applied to data drift and forgetting [11]. Other work addresses performance degradation through meta-learning [10] and compares continual learning methods for intrusion detection [12]. The studies in this group are mainly motivated by drift and new traffic rather than by an adversary who responds to the deployed model."));
body.push(P("The closest prior work we identified on dynamic NIDS under evasion is by elShehaby and Matrawy [13]. It is a preprint (arXiv:2306.05494, current version titled “Evasion Adversarial Attacks Remain Impractical Against ML-based Network Intrusion Detection Systems, Especially Dynamic Ones”) and has not been confirmed as peer reviewed. According to its abstract, it uses an attack-tree threat model to identify practicality barriers to evasion, and it studies how regularly updated, dynamic models respond to such attacks. It reports that continuous retraining can reduce attack effectiveness even without adversarial training [13]. This is directly relevant to our question, and it shows that dynamic NIDS under evasion has been examined."));
body.push(P("The present study differs in its design. It evaluates bounded, feedback-driven updates that use newly successful evasions, compares incremental updating with one-time adversarial training and with a clean-continued control, and applies a common per-round attacker budget to every update policy. The labels used for those updates are simulated from dataset ground truth and are not analyst-confirmed. The two replay-based arms in our design, incremental updating with a clean rehearsal memory and the balanced-replay variant, follow the replay approach in [27]. [26] documents the forgetting problem that the no-rehearsal arm is designed to expose."));
body.push(H2("2.5 Evaluation practice and the dataset"));
body.push(P("Arp et al. catalog recurring pitfalls in the evaluation of learning-based security systems, including tuning on test data [29]. Their work supports general caution of this kind. It does not prescribe any particular operating point, and the 5% value used here is this study's own protocol. For each model checkpoint, the threshold is selected on validation data to target at most 5% validation FPR, and the test set is not used for tuning. Test FPR is measured separately and is not constrained to 5%. Section 5.1 reports the resulting test FPR values. We therefore describe the primary analysis as a validation-calibrated threshold comparison, and not as a comparison at equal test-set operating points."));
body.push(P("Robustness estimates can also be optimistic when the attack is weaker than one a defender would face. Carlini and Wagner showed that several proposed defenses could be circumvented by stronger attacks [30], and Tramèr et al. showed that several published defenses, evaluated against non-adaptive attacks, were broken by adaptive ones [31]. This matters here because the attacker in this study is non-adaptive (Section 6.5)."));
body.push(P("The evaluation uses UNSW-NB15 [14]. Zoghi and Serpen report class overlap and imbalance in UNSW-NB15 and show that adjusting the decision threshold is one way to handle them [15]. This supports reporting FPR and threshold choice explicitly, and it is one reason a single fixed threshold is not assumed to remain appropriate after a model is updated. Axelsson argued that, because intrusions are rare relative to benign activity, the false-alarm rate is often the limiting factor in intrusion detection performance [32]."));
body.push(H2("2.6 Research Gap"));
body.push(P("Three points emerge from the reviewed studies. First, adversarial training and related defenses can improve robustness against the attacks used in their own evaluations, and some of them report clean-data behavior alongside robustness [6]–[9]. Second, several of the attacks reviewed perturb feature vectors directly, and whether the perturbed records correspond to valid traffic is a separate question [4], [5], [23], [24]. Third, the continual-learning studies we reviewed are framed mainly around drift and forgetting, and the abstracts we read do not describe updates driven by evasions [10]–[12], [26]–[28]."));
body.push(P("Two recent studies come closer in structure to this design than the preprint discussed in Section 2.4 [13]. In the first, a reinforcement learning attacker changes its perturbation strategy across alternating rounds against an XGBoost detector trained on CICIDS-2017 and the ACI IoT 2023 dataset, while a reinforcement learning defender chooses after each data batch among online learning, active learning, continual learning, and pseudo labeling. The active-learning option queries labels [33]. In the second, contrastively trained reinforcement learning attackers, each learning a distinct perturbation strategy on CICIDS-2017 packet features, are deployed in sequence against an XGBoost detector, while a reinforcement learning defender chooses among online learning, active learning, continual learning, and pseudo labeling. The authors report that post-attack accuracy fell to an average of 35% in their runs despite retraining [34]. We read the full texts of both studies. Both model attackers that change strategy across rounds against an updating defender, which the present study does not. Both report accuracy as their main outcome, and neither reports clean false-positive rates, label counts, or query counts for the update policies compared here."));
body.push(P("Against this background, among the studies we reviewed we did not find a direct comparison in which a detector is updated repeatedly from its own successful evasions, against a non-adaptive attacker, and compared with a one-time adversarial training step under a shared dataset, attack schedule, and per-round attacker budget, with clean recall, false-positive rate, label counts, and query counts reported together. The gap is specific to the studies reviewed here. It concerns how repeated, evasion-driven updating compares with one-time training under a common protocol when the attacker does not respond to the defender. It does not concern whether adaptive or dynamic defenses have been studied at all."));
body.push(P("This study addresses that gap in a limited setting, and only for the configurations it tests. It compares five update policies with a clean-continued control on UNSW-NB15 over five rounds. The arms share a per-round attacker budget. Each arm is attacked at its own current model with the same number of flows, the same perturbation bound, and the same query limit for the decision-only attack. The arms do not receive matched amounts of adversarial training data, however. The one-time static arm trains on 500 pre-built adversarial examples. The incremental arms update from the successful evasions of each round, and arms C and E also replay a fixed memory. Labels for successful evasions are simulated from dataset ground truth, and no analyst reviewed them. Because the training-data budgets differ, the comparison describes the configurations tested. It does not isolate the causal effect of the update strategy alone. Section 3 states the aim, objectives, and research questions."));

// ===== Section 4 =====
body.push(H1("3. Study Aim, Objectives and Research Questions"));
body.push(H2("3.1 Aim"));
body.push(P("The aim of this study is to compare, round by round, how a network intrusion detector responds under different ways of updating it from its own newly successful evasions. The comparison covers attack outcomes, clean-traffic detection, simulated feedback labels, adaptation-stage queries, and training and attack time. The study is exploratory. It does not assume that incremental updating is better, and its results describe the configurations tested, not deployed robustness."));
body.push(P("The motivating scenario is a contest between an attacker, who adapts to a deployed detector, and a defender, who responds by updating from successful evasions. The experiment does not model that contest. The attacker is non-adaptive. In each round it attacks each policy's current model with the malicious flows drawn from that round's adaptation batch, and it does not learn from earlier rounds or from the defender's updates (Section 4.4)."));
body.push(H2("3.2 Objectives"));
body.push(P("**O1.** Review the literature on evasion attacks and defenses for NIDS, and place the study's threat model within it (Section 2).", { indent: { left: 360 } }));
body.push(P("**O2.** Train a baseline multilayer perceptron on the official UNSW-NB15 partitions, and report its clean detection behavior (Sections 4.2, 4.3, and 5.4).", { indent: { left: 360 } }));
body.push(P("**O3.** Attack each update policy over five successive rounds under the same per-round attacker budget, and record in each round the outcome against that policy's current detector (Sections 4.4, 4.7, 5.2, and 5.6).", { indent: { left: 360 } }));
body.push(P("**O4.** Operationalize incremental updating from newly successful evasions. The primary configuration is incremental updating with clean rehearsal (arm C), which is intended to limit forgetting. It is compared with a no-rehearsal ablation (arm D), a balanced-replay variant (arm E), a one-time static adversarial arm (arm B), and a clean-continued control (arm F). These arms operationalize and compare incremental updating and are not presented as validated defenses (Sections 4.5, 5.2, and 5.3).", { indent: { left: 360 } }));
body.push(P("**O5.** Measure the cost of each policy in clean-side detection (clean recall, FPR, F1, and AUC), simulated feedback labels, adaptation-stage queries of the decision-only attacker, and training and attack time (Sections 4.7, 5.4, and 5.7).", { indent: { left: 360 } }));
body.push(P("**O6.** Over 20 seeds, compare one-time and incremental schedules that train on the same number of attack attempts made on the same 500 source flows, under the same rule within each update, including a one-time arm that also matches the incremental schedule's optimizer steps and per-example exposure. In the FGSM-like setting, check how sensitive the comparison is to update epochs, learning rate, and memory size (Sections 4.9, 5.8, and 5.9).", { indent: { left: 360 } }));
body.push(P("**O7.** Measure how far the perturbations move flows in raw feature units and whether perturbed flows keep relations among features that hold in the data (Sections 4.4 and 5.10).", { indent: { left: 360 } }));
body.push(H2("3.3 Research Questions"));
body.push(P("We address five research questions. RQ1 to RQ4 concern the original five-seed comparison, and RQ5 concerns the matched-attempt extension."));
body.push(P("**RQ1.** In each round, how does attack-induced ASR against the incremental arms (C, D, and E) compare with that of the frozen arm (A) and the one-time static arm (B), when each arm uses a threshold selected on its own validation data to target at most 5% validation FPR? (Sections 5.2, 5.3, and 5.6)", { indent: { left: 360 } }));
body.push(P("**RQ2.** What clean-traffic costs accompany changes in attack-induced ASR, in recall, false-positive rate, F1, and AUC, and how much of any fixed-threshold difference remains once validation-calibrated thresholds replace the common fixed threshold? (Sections 5.4 and 5.5)", { indent: { left: 360 } }));
body.push(P("**RQ3.** How does the clean-continued control (arm F) compare with the frozen (arm A) and static (arm B) arms in round-wise attack-induced ASR and in clean-side measures? (Sections 5.3 and 5.4)", { indent: { left: 360 } }));
body.push(P("**RQ4.** How do simulated feedback labels, adaptation-stage queries of the decision-only attacker, and training and attack time compare across the update policies? The time measure excludes test-time evaluation. (Section 5.7)", { indent: { left: 360 } }));
body.push(P("**RQ5.** When one-time and incremental schedules train on the same number of attack attempts made on the same source flows, under the same rule within each update, how do their round-5 attack-induced ASR and clean-side measures compare, and how does the comparison change when the one-time update's length or structure is changed to match training exposure? (Sections 5.8 and 5.9)", { indent: { left: 360 } }));
body.push(H2("3.4 Scope and Contributions"));
body.push(P("The study does not test an attacker that adapts across rounds, the packet-level feasibility of perturbed flows, other datasets or detector architectures, or comparisons with architectural defenses or external benchmarks. The decision-only attacker also makes evaluation-stage queries when it measures attack-induced ASR on the evaluation set. These are recorded in the analysis files and are not compared in this paper, and they are separate from the adaptation-stage queries reported for RQ4. Clean F1 is reported with clean recall, FPR, and AUC (Section 4.7)."));
body.push(P("The study makes four contributions. It provides a round-by-round comparison of update policies that includes a clean-continued control, which gives a descriptive comparison of extra clean training. It adds a 20-seed extension that matches the number and source-flow set of attack attempts across one-time and incremental schedules, including one one-time arm that also matches the incremental schedule's optimizer steps and per-example exposure. It reports attack-induced ASR beside the false-positive rate of each policy, at both validation-calibrated and common fixed thresholds, so that attack-induced ASR is not read in isolation. It measures how far the feature-space perturbations move flows in raw units and how often they break relations that hold in the data. The five-seed results are descriptive. The 20-seed results are reported as paired differences with intervals and seed counts, and neither set is used to claim that any policy is generally superior."));
body.push(H1("4. Methodology"));
body.push(P("This section describes the experiment whose results are reported in Section 5. Every setting below was taken from the run scripts and the run metadata of the completed five-seed experiment (seeds 17 to 21). Nothing is described here that was not run."));

body.push(H2("4.1 Experimental design"));
body.push(P("Figure 1 maps the experiment. For each seed, the official training partition is divided into an initial training set, a validation set, and an adaptation stream. Six detectors, called arms and defined in Section 4.5, start from the same data split and the same initial weights and training procedure. Two of them, the static adversarial arm and the clean-continued control, receive extra training before round 1. The experiment then runs for five rounds. In each round, 100 malicious flows are drawn from that round's slice of the adaptation stream, and each arm's current model is attacked. Only the three incremental arms use the successful evasions to update. After every round, each arm is evaluated on the held-out test partition with a fresh attack against its current model."));
body.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 120, after: 60 }, keepNext: true,
  children: [new ImageRun({ type: "png", data: fs.readFileSync("/mnt/user-data/outputs/paper/figures/fig1_experiment_map.png"),
    transformation: { width: 520, height: 404 }, altText: { title: "Figure 1", description: "Round-by-round map of the six arms, five rounds, and evaluation", name: "fig1" } })] }));
body.push(caption("**Figure 1.** Round-by-round map of the experiment. Rows are the six update arms. The columns show the preparation before round 1, the steps repeated in each of rounds 1 to 5, and the evaluation applied after every round. Colors mark the update policy. Each arm is attacked at its own current model, so no arm receives evasions generated against another arm."));
body.push(P("Figure 1 shows what is shared and what differs. The data split, the initial weights, the round schedule, the per-round attack sample, and the evaluation procedure are the same for every arm. The arms differ only in the preparation they receive before round 1 and in whether and how they update during the rounds. Differences in outcome therefore do not come from different attack budgets or evaluation sets. They are not causal estimates of the effect of an update policy either, because the arms also differ in their training data and budgets. The clean-continued control matches the static arm's extra training epochs without adversarial examples, so it gives a descriptive comparison of extra clean training under the tested configuration. Because the two arms also differ in their adversarial examples, the comparison does not isolate the effect of either. The held-out test partition is used only for evaluation. It is never used to fit, to update, or to choose a threshold."));

body.push(H2("4.2 Dataset and partitions"));
body.push(P("We used UNSW-NB15 [14], with the pre-partitioned train/test split as redistributed in the Zenodo record [35]. That record lists the two partition files under reversed names. The file named UNSW_NB15_testing-set.csv holds the 175,341 training records, and the file named UNSW_NB15_training-set.csv holds the 82,332 test records. The partitions were identified by these row counts, and the loader assigns them to these roles. The files are tab-separated and have no header row, although their extension is .csv. The loader detects the delimiter from the first 4,096 characters of each file and assigns the 45 column names of the published UNSW-NB15 schema in the published order, from id to attack_cat and label. The Zenodo record is a third-party redistribution, not the official source. For this revision we downloaded both files from the record again. Their MD5 checksums equal the values the record lists and the values in the experiment records. The official UNSW-NB15 page describes a training partition of 175,341 records and a test partition of 82,332 records [36]. We downloaded the official test partition from that source and compared it with the 82,332-record Zenodo file. All 82,332 records, matched by record identifier, are identical in all 45 columns. The official training partition could not be downloaded in this revision, so the 175,341-record file is verified only against the Zenodo checksum. The task is binary classification, with the supplied label coded as benign (0) or malicious (1). The record identifier and the attack category column were not used as inputs or targets."));
body.push(P("For each seed, the training partition was split at the record level into initial training, validation, and adaptation parts, using a 70/15/15 allocation stratified by class. The test partition was never resampled. Table 2 gives the resulting counts, which are the same for every seed because the stratified allocation is deterministic in size."));
body.push(caption("**Table 2.** UNSW-NB15 record counts and experimental roles. Partition sizes follow from the split procedure and the file sizes in the experiment records. All counts were checked against the downloaded files for every seed used (17 to 36), and the split sizes are identical across seeds.", true));
body.push(table([2000, 1200, 1300, 1200, 3660],
  ["Partition", "Benign", "Malicious", "Total", "Role"],
  [
    ["Initial training", "39,200", "83,538", "122,738", "Fit the preprocessor and the initial detector, source of replay memories and static examples"],
    ["Validation", "8,400", "17,901", "26,301", "Threshold selection only"],
    ["Adaptation stream", "8,400", "17,902", "26,302", "Source of the 100 malicious flows attacked in each round"],
    ["Official test", "37,000", "45,332", "82,332", "Evaluation only"],
    ["Total", "93,000", "164,673", "257,673", "Official training plus test partitions"],
  ]));
body.push(gap());
body.push(P("Table 2 shows that the validation and adaptation parts are each about 15% of the training partition and that the test partition is kept entirely apart. The split is at the record level and does not group records by capture session, source, or attack campaign. Related records could therefore occur in more than one of the initial-training, validation, and adaptation parts, which is a risk of dependence between partitions and of optimistic measured performance, and not demonstrated leakage. The official test partition was kept apart and was not split in this way. Evaluation designs that do not respect temporal structure can inflate reported performance in malware classification [37]. UNSW-NB15 is also known to contain class overlap and imbalance [15]. For these reasons the experiment is a controlled benchmark comparison and not a claim about deployment performance."));

body.push(H2("4.3 Preprocessing and detector"));
body.push(P("The preprocessor was fit on the initial training part only and then applied unchanged to the validation, adaptation, and test data. Numeric fields had infinite values treated as missing, missing values replaced by the initial-training median, and values scaled to the range 0 to 1 using the initial-training minimum and maximum, with out-of-range values clipped, and columns with no range in the initial training part were divided by one. Categorical (non-numeric) fields were one-hot encoded using the levels observed in the initial training part, and unseen levels map to all zeros, and missing categorical values were coded as a separate level. The input dimension is 194 for seeds 17, 19, 20 and 21 and 193 for seed 18, which reflects the categorical levels present in each seed's initial part."));
body.push(P("The detector is a multilayer perceptron with one hidden layer of 48 ReLU units and a single sigmoid output. It was implemented in NumPy and trained with binary cross-entropy and the Adam optimizer [38] (learning rate 0.001, batch size 256, 5 epochs) on the initial training part. Initial weights were drawn from a normal distribution with variance 2 divided by the layer's fan-in, using a seed set for each run, and the biases started at zero. The Adam moment estimates persist when a model is updated later. The detector is small, and the conclusions of this paper are limited to models of this kind."));

body.push(H2("4.4 Threat model and attack settings"));
body.push(P("The attacker's goal is to make a malicious flow be classified as benign. The attacker may change only 11 continuous features (dur, rate, sload, dload, sinpkt, dinpkt, sjit, djit, tcprtt, synack and ackdat). Each may move by at most ε = 0.03 in the normalized space (an L∞ bound, so each feature may change by up to 0.03 independently of the others) and stays within the range 0 to 1. All other features, including the one-hot categorical inputs, are left unchanged. In each round the attacker meets the arm's model as it exists at that moment and has the same budget against every arm. There is no attacker that accumulates knowledge or strategy across rounds. Table 3 summarizes the three attack settings."));
body.push(caption("**Table 3.** Attack settings, attacker access, and budgets. All settings perturb the same 11 normalized features with ε = 0.03.", true));
body.push(table([1300, 1800, 2700, 2100, 1460],
  ["Setting", "Attacker access", "Procedure", "Volume per run", "Static-arm training examples"],
  [
    ["FGSM-like [18]", "Gradients of the arm's current model", "One step of size ε along the sign of the gradient of the loss for the benign label (target 0)", "100 flows per round for updates, 1,000 flows for each evaluation", "FGSM-like"],
    ["BIM-like [19]", "Gradients of the arm's current model", "Five steps of size ε/5, each followed by projection into the ε-ball and clipping, no random start", "Same as FGSM-like", "BIM-like"],
    ["Decision-only", "Hard labels only, no scores or gradients", "Random search. The original flow is queried first, then up to 49 random candidates within the ε-box, stopping at the first one labeled benign", "At most 50 queries per flow, so at most 5,000 queries per round for updates and 50,000 for each evaluation", "FGSM-like (cross-attack)"],
  ]));
body.push(gap());
body.push(P("Table 3 shows that the three settings differ in what the attacker can observe and not in what the attacker may change. The FGSM-like and BIM-like attacks follow the single-step and iterative gradient methods described in [18] and [19]. We call the five-step attack BIM-like and not PGD [20], because it has no random start. The decision-only attack is a plain random search in the hard-label setting studied in [22]. This is a deliberately simple, unoptimized random-search baseline. Its results characterize the configured attack and should not be interpreted as an estimate of the strongest achievable decision-only attack. In the decision-only evaluation, the static arm is trained using FGSM-like examples, so this is a cross-attack comparison rather than a threat-model-matched static baseline."));
body.push(P("All attacks operate on feature vectors. We did not reconstruct packets and did not check that a perturbed vector corresponds to traffic that could be sent while keeping its protocol validity and malicious function, the properties discussed in [4]. Because each feature is min-max scaled on the initial training part, the bound of 0.03 allows a change of at most 3% of that feature's range in the initial training part, and perturbed values are clipped so that they stay within that range. The attack changes each of the 11 features independently and does not enforce any relation among them or with unperturbed fields such as byte and packet counts. Section 5.10 reports how large these perturbations are in raw units and how often they break two relations that hold in the data. Attack-induced ASR therefore describes how sensitive a detector is to bounded feature perturbations."));

body.push(H2("4.5 Update arms and simulated feedback"));
body.push(P("Table 4 defines the six arms. Tables and text refer to them by letter and short name: frozen (A), static (B), rehearsal (C), no rehearsal (D), balanced (E), and control (F). The arms A, C, D and E receive identical initial training. The static arm (B) and the clean-continued control (F) add a second training phase of five epochs before round 1. For arm B, that phase includes 500 adversarial examples, which are perturbed copies of malicious flows from the initial training part, generated against the clean model fitted on the initial training part and all labeled malicious whether or not the perturbation succeeded. In each setting the examples come from that setting's gradient attack, FGSM-like in the FGSM-like setting and BIM-like in the BIM-like setting, and the decision-only setting uses FGSM-like examples (Section 4.4). For arm F, the phase repeats the clean initial training data with no adversarial examples. The incremental arms (C, D and E) update after each round for two epochs on the evasions found in that round, with or without a replay memory. The rehearsal memory is a random sample of 1,000 clean examples from the initial training part, which follows the replay approach in [27] and is intended to limit forgetting. The balanced memory holds 500 benign and 500 malicious examples from the same part. Arm D is the no-rehearsal ablation, and [26] documents the forgetting problem that this ablation is designed to expose."));
body.push(caption("**Table 4.** Update arms. Learning rate is 0.001 unless stated, and all updates use batch size 256.", true));
body.push(table([1500, 2100, 2800, 2960],
  ["Arm", "Before round 1", "Update after each round", "Purpose"],
  [
    ["A. Frozen clean", "Clean fit, 5 epochs", "None", "No-update reference"],
    ["B. Static adversarial", "Clean fit, then 5 more epochs on the clean data plus 500 adversarial examples", "None", "One-time adversarial preparation"],
    ["C. Incremental with rehearsal", "Clean fit, 5 epochs", "2 epochs on new evasions plus a fixed 1,000-example clean memory", "Primary incremental configuration, with a memory intended to limit forgetting"],
    ["D. Incremental without rehearsal", "Clean fit, 5 epochs", "2 epochs on new evasions only (all labeled malicious)", "No-rehearsal ablation"],
    ["E. Balanced replay", "Clean fit, 5 epochs", "2 epochs on new evasions plus a 500/500 benign and malicious memory, learning rate 0.0002", "Balanced-replay variant"],
    ["F. Clean-continued control", "Clean fit, then 5 more epochs on the clean data", "None", "Descriptive comparison of extra clean training. Does not isolate causal effects"],
  ]));
body.push(gap());
body.push(P("Table 4 shows that the arms form a ladder of interventions. Arm B adds adversarial examples to extra training, arm F receives the extra training without adversarial examples, and arms C to E ask whether repeated feedback adds anything. Because arm D updates only on evasions, every example in its updates is malicious. This update composition may shift the model's scores or operating behavior, and Section 5 evaluates the resulting recall and false-positive rates under both threshold analyses."));
body.push(P("Arm C is the primary incremental configuration because it includes clean rehearsal. Arm D is the no-rehearsal ablation: it uses the same updates as arm C, without the clean memory. Arm E is the balanced-replay variant, which replaces the clean memory with a balanced memory and uses a lower learning rate. Rehearsal is intended to mitigate forgetting. In an NIDS evaluation of continual learning strategies, the abstract reports that replay was the most effective way to ameliorate catastrophic forgetting and that regularization strategies were ineffective [12]. The present experiment does not measure forgetting of earlier attacks directly, so it does not establish that rehearsal reduces forgetting here, and arm C is not presented as superior to the other incremental arms."));
body.push(P("The feedback for the incremental arms is simulated. In each round, a flow counts as a successful evasion if its perturbed version is classified as benign at the common fixed threshold described in Section 4.6. Its label is then taken from the dataset ground truth, which acts as an idealized oracle. The labels are not analyst-confirmed, and no analyst delay, disagreement, or labeling error is modeled. The attack-attempt budget is matched across arms, at 100 flows per round. The label budget is not matched. The static arm uses 500 pre-built examples, while the number of labels in each incremental arm depends on how many attempts succeed."));

body.push(H2("4.6 Thresholds and operating points"));
body.push(P("Two kinds of threshold are used. The first is a common fixed threshold. For each seed, it is the smallest candidate threshold at which the initial clean model's false-positive rate on the validation set is at most 5%. It ranges from 0.736 to 0.775 across seeds. It is held fixed for all arms and rounds. It defines which test flows are eligible for evaluation, it decides whether an update-stage attack succeeded, and it supports the secondary fixed-threshold analysis."));
body.push(P("The second is an arm-specific threshold. After each round, the same rule is applied to each arm's current model on the same validation data, which gives that checkpoint's own threshold. The observed validation FPR at these thresholds was between 4.99% and 5.00%. The primary analysis uses these thresholds, and we call it a validation-calibrated threshold comparison. The reason is that updating changes how a model scores flows, so one fixed threshold can correspond to different false-positive rates for different models. The test set is never used to choose either threshold, which follows the general caution against tuning on test data in [29]. Test FPR is measured separately. It is not constrained to 5% and it differs between arms, so the comparison is not one at equal test-set operating points."));

body.push(H2("4.7 Outcome measures and analysis"));
body.push(P("Table 5 defines the outcome measures. The evaluation set contains, for each seed, up to 1,000 malicious test flows drawn at random from the malicious test flows that the initial clean model detects at the common fixed threshold. It is fixed across arms, rounds, and attack settings, and in all runs it contained 1,000 flows. In each evaluation, every arm's current model is attacked afresh on this set."));
body.push(caption("**Table 5.** Outcome measures. All rate measures are reported in percentage points except AUC.", true));
body.push(table([2100, 5300, 1960],
  ["Measure", "Definition", "Threshold"],
  [
    ["Pre-attack detection rate", "Share of the fixed evaluation cohort that the arm's current model detects before any perturbation", "Arm-specific (primary), fixed (secondary)"],
    ["Attack-induced ASR (primary)", "Among evaluation flows detected before perturbation, the share classified benign after perturbation", "Arm-specific (primary), fixed (secondary)"],
    ["Post-attack benign rate, all evaluation flows (secondary)", "Share of the whole evaluation cohort classified benign after perturbation, including flows the arm already classified as benign before the attack. It is not a count of evasions caused by the attack", "Arm-specific, fixed"],
    ["Clean recall and FPR", "Recall on malicious test flows and false-positive rate on benign test flows, measured on the full test partition without perturbation", "Arm-specific (primary), fixed (secondary)"],
    ["Clean F1", "F1 score of the malicious class on the full test partition without perturbation, computed from the same confusion matrix as clean recall and FPR, at the same threshold", "Arm-specific (primary), fixed (secondary)"],
    ["Clean AUC", "Area under the ROC curve on the full test partition, a threshold-free measure of ranking quality", "Not applicable"],
    ["Simulated labels", "Cumulative number of successful evasions used for updates. Static training uses 500 pre-built examples and no post-deployment labels", "Common fixed"],
    ["Adaptation-stage queries", "Hard-label queries made by the decision-only attacker on each round's adaptation sample (100 flows per round, at most 50 queries per flow), summed over five rounds (reported in Section 5.7)", "Per setting"],
    ["Evaluation-stage queries", "Hard-label queries made by the decision-only attacker when running the decision-only attack against the 1,000-flow evaluation set at each round. They are recorded in the analysis files and are not compared in this paper", "Per setting"],
    ["Training and attack time", "Cumulative wall-clock time in one process: initial training, the static arm's example generation and extra training, and, in each round, attack generation and update training for every arm against its own current model. Test-time evaluation is excluded", "Not applicable"],
  ]));
body.push(gap());
body.push(P("The primary attack measure is attack-induced ASR at validation-calibrated thresholds, the share of flows an arm detects before perturbation that the attack then moves to the benign side. Table 5 shows why a second, complementary measure, the post-attack benign rate, is reported alongside it. A flow that an arm already classifies as benign before perturbation is counted in the post-attack benign rate whatever the attacker does, so that rate mixes flows the attack moved with flows the arm had already missed, and an arm whose sensitivity falls can show a higher rate for reasons unrelated to the perturbation. It should be read as the share of the cohort that ends up classified benign, and not as a count of attack-induced evasions. The attack-induced measure conditions on flows detected before perturbation, which isolates the effect of the perturbation, but its denominator differs between arms. We therefore report the pre-attack detection rate beside it, together with clean recall, FPR, and AUC, so that a low attack-induced ASR obtained by losing sensitivity or flagging benign traffic is visible."));
body.push(P("Results are reported at round 5 and as round-by-round trajectories. For each arm and attack setting, we report the mean over the five seeds with a 95% Student t interval (4 degrees of freedom). For contrasts between two arms we report the mean of the per-seed differences, its t interval, and the number of seeds in which the first arm was lower. Pairing by seed is natural because arms in the same seed share the split and the initial model. These intervals are descriptive. We run no hypothesis tests and make no multiplicity adjustment, and with five seeds the intervals are wide, so we describe patterns and trade-offs and do not claim statistical superiority. The 20-seed extension (Section 4.9) is analyzed the same way, with 19 degrees of freedom. For it we also give, as a descriptive check, an exact two-sided sign test on the number of seeds in which the first arm was lower, without multiplicity adjustment."));

body.push(H2("4.8 Implementation and reproducibility"));
body.push(P("The experiment is implemented in Python with NumPy, including the detector and the attacks. The full matrix consists of 15 runs (5 seeds by 3 attack settings), each producing 30 rows (6 arms by 5 rounds), for 450 rows in total. Random streams are seeded per run, and the per-run metadata record the input dimension, partition sizes, common fixed threshold, attack settings, and the number of perturbed features. The reported five-seed outputs were produced before this revision, in an environment that was not recorded. For this revision we re-ran the archived runner on the downloaded data (Python 3.13.17, NumPy 2.5.3, pandas 3.0.5). Five of the 15 runs matched the reported per-run outputs to within float32 rounding (about 10⁻⁷) in every non-timing column, three matched to within 3 × 10⁻⁵, and seven showed small numerical drift. In one seed the initial model's fixed threshold differed slightly, and single round values then differed by up to 3.3 points. The five-seed round-5 means of every rate measure differed from the reported means by at most 0.46 points (0.41 points for calibrated attack-induced ASR). In the seed-paired contrasts of Section 5.3, every seed count was unchanged except rehearsal against frozen in the decision-only setting, which moved from 2 to 3 of 5 seeds with a mean difference near zero. We read this as reproduction with small numerical differences, consistent with the same code running in a different numerical environment, and not as bit-for-bit reproduction. Because the original environment and the exact original code version were not recorded, the rerun does not prove that the archived runner is the code that produced the original outputs. The results in Sections 5.2 to 5.7 report the original outputs. For the five arms shared with the earlier final matrix in the experiment bundle, the clean-side outputs and the fixed-threshold post-attack benign rates match that matrix in every setting, round, and seed compared, on every column that both versions record. The reported runs used all training-file rows, with five rounds and five epochs. The runner's default cap of 30,000 rows and its two-round default are pilot settings and were not used. The attack-induced, pre-attack detection, arm-specific threshold and AUC columns, and the clean-continued control, were added for this study. A random-start PGD variant was not run. Timing values come from in-process wall-clock measurements on one machine and are not normalized across hardware. Each of the 15 runs records a cumulative time for each arm, and Section 5.7 reports the mean over the five seeds for each setting. The initial training of the frozen arm, which follows the same procedure in every run, took between 0.432 and 0.452 seconds across the 15 runs (mean 0.440 seconds, standard deviation 0.006 seconds). Differences of a few hundredths of a second between arms are small relative to these figures and to the attack-generation costs described in Section 5.7, and they are not interpreted as differences in the cost of a policy. The availability of the data and code is described in the Data and Code Availability statement."));

body.push(H2("4.9 Matched-attempt extension and sensitivity analysis"));
body.push(P("The extension was designed, and its design written down, before its first runs. It uses seeds 17 to 36 and keeps the data, split, preprocessing, detector, attack settings, per-round attacker budget, evaluation cohort, and threshold rules of the main comparison. The six original arms run unchanged inside the same runs. The extension was run in the reproduction environment of Section 4.8, so for seeds 17 to 21 its values for the shared arms equal the rerun outputs, which differ slightly from the original outputs reported in Sections 5.2 to 5.7."));
body.push(P("The extension matches the number and the source-flow set of attack attempts. It does not match the perturbed feature vectors themselves. One attempt is one attacked malicious flow, labeled malicious from the dataset ground truth and used for training whether or not the perturbation evaded the target model. Rounds 1 to 5 attack the same 100 adaptation flows in every arm, because these flows are chosen by the seed and the adaptation stream and not by any model, so every matched arm trains on attempts made on the same 500 source flows. The vectors can differ, because the one-time arms generate theirs against the initial model before round 1, while the matched all-attempt incremental schedule generates each round's vectors against its model as it changes across rounds. Unlike the original incremental arms C, D, and E, which update only on successful evasions, the matched incremental schedule trains on all 100 attempts in each round, so it is a different update policy from those arms."));
body.push(P("Table 6 lists the matched arms. All use the same rule within each update, namely the attempts plus the 1,000-example clean memory, learning rate 0.001, and batch size 256. They differ in how many updates they make, how long each lasts, and which model the vectors were generated against."));
body.push(caption("**Table 6.** Arms of the matched-attempt extension. M1, M1-e10, M1-seq, and M2 train on 500 attempts from the same 500 adaptation flows, labeled malicious. B-dec, like the original static arm, uses 500 flows from the initial training part. Epoch columns give how many epochs each adversarial vector and the clean memory are seen in total.", true));
body.push(table([2300, 1350, 1100, 1550, 900, 950, 1210],
  ["Arm", "Updates", "Epochs per update", "Vectors generated against", "Epochs per vector", "Clean-memory epochs", "Declared"],
  [["M1, matched one-time", "1, before round 1", "2", "Initial model", "2", "2", "Before any run"], ["M1-e10, matched one-time, 10 epochs", "1, before round 1", "10", "Initial model (M1's vectors)", "10", "10", "Before any run"], ["M1-seq, matched one-time, five sequential updates", "5, all before round 1", "2", "Initial model (M1's vectors)", "2", "10", "After the first matched results, before its own runs"], ["M2, matched all-attempt incremental", "5, one after each round", "2", "M2's current model in each round", "2", "10", "Before any run"], ["B-dec, static with decision-only examples (decision-only setting)", "1, before round 1", "5, on the initial training part plus the examples", "Initial model, decision-only attack", "5", "Not applicable", "Before any run"]]));
body.push(gap());
body.push(P("M1 and M2 differ in three ways at once: when the vectors are generated and which model they target, the number of updates, and the total exposure (one two-epoch update for M1, five for M2). M1-e10 makes one ten-epoch update. It matches M2's total epochs over the clean memory but sees each adversarial vector for ten epochs instead of two. M1 and M1-e10 were declared before any run. M1-seq was added after the results of M1, M1-e10, M2, and the sensitivity analysis were known, in response to review, and its design was written down before any of its runs. It applies M1's 500 vectors in M2's update structure, as five consecutive two-epoch updates before round 1, each on one round's group of 100 vectors plus the clean memory, with the same shuffling seeds as M2's updates. M1-seq and M2 therefore match update calls, optimizer steps, batch sizes, and per-vector and clean-memory exposure, and at round 5 both have completed all five updates. What still differs between them is the model each vector was generated against. M1 and M1-seq use the same vectors and differ only in update structure. Wall-clock compute was not matched."));
body.push(P("In the decision-only setting, the matched arms use decision-only attempts. A failed decision-only attempt leaves the flow unperturbed, and it still counts as one attempt. A further arm, B-dec, repeats the original static procedure with 500 decision-only attempts generated against the initial model at the common fixed threshold, as the threat-model-matched counterpart of the static arm in that setting."));
body.push(P("The contrasts were listed before the runs: M1 against M2, M1-e10 against M2, the static arm against M1, the static arm against B-dec, and the main comparison's contrasts of Section 5.3, repeated over 20 seeds. The M1-seq contrasts (M1-seq against M2, M1 against M1-seq, and M1-seq against the frozen arm) were listed in the addendum before its runs. All are reported. A separate sensitivity analysis, declared before the extension's runs, varies one update setting at a time over the same 20 seeds, in the FGSM-like setting only. Update epochs take the values 1 and 4 (default 2), the learning rate 0.0005 and 0.002 (default 0.001), and the clean-memory size 500 and 2,000 (default 1,000). These settings apply to arms C, M1, M1-e10, and M2, with M1-e10 using five times the update epochs. M1-seq was not part of the sensitivity analysis. Every configuration is reported, none is selected as best, and thresholds are still chosen on validation data only."));

